const express = require('express');
const app = express();

// Step 1: Authentication (Who are you?)
function authenticateUser(req, res, next) {
  const token = req.headers['authorization'];
  if (!token) {
    return res.status(401).json({ error: 'Authentication required: missing token' });
  }

  // Verify token and attach user identity
  const user = verifyToken(token);
  if (!user) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }

  req.currentUser = user;
  next();
}

// Step 2: Authorization (What are you allowed to do?)
function authorizeRole(requiredRole) {
  return (req, res, next) => {
    if (!req.currentUser || req.currentUser.role !== requiredRole) {
      return res.status(403).json({ error: 'Forbidden: insufficient permissions' });
    }
    next();
  };
}

// Applying both in order: Authenticate first, then Authorize
app.delete('/api/admin/users/:id', authenticateUser, authorizeRole('admin'), (req, res) => {
  res.json({ message: 'User deleted successfully' });
});

